"""Owner-only, local browser import for personal provisional pre-day forecast files.

Does not call JRDB, copy licensed rows to public pages, touch ticket or result
storage, claim official JRA readiness, or imply betting has occurred.
"""
HTML="<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#09172b\"><title>KEIBA NINE｜本人用の前日予想</title><link rel=\"stylesheet\" href=\"/owner-preday-forecast.css\"></head><body><main><a href=\"/\">← 本人用ホームへ</a><h1>本人用・暫定予想</h1><p class=\"warning\"><b>本人用・前日暫定予想の閲覧ページです。</b> 予想は本人ログイン後に自動読み込みします。接続できない場合だけ保存済みの端末ファイルを使えます。5項目AIの正式評価、JRA公式の当日取消・馬場照合、購入済み馬券ではありません。見送りRも参考の組合せを表示します。過去の開催日の予想は自動的に非表示にします。</p><section><h2>配信されている開催日の予想</h2><p class=\"hint\" id=\"fpCloudStatus\" role=\"status\">本人用の非公開予想を確認中です。読み込みにファイル選択は不要です。</p><button id=\"fpRefresh\" type=\"button\">最新版の予想を再読み込み</button><p class=\"hint\" id=\"fpLiveStatus\" role=\"status\">JRDB当日の直前情報を確認中です。</p><p class=\"hint\" id=\"fpMailBridgeStatus\" role=\"status\">Gmail自動連携の接続状態を確認中です。</p><p class=\"hint\" id=\"fpEvidenceStatus\" role=\"status\">各Rの根拠を読み込み中です。</p><div class=\"venue-tabs\" id=\"fpVenueTabs\" role=\"group\" aria-label=\"競馬場を選ぶ\"></div><div class=\"race-tabs\" id=\"fpRaceTabs\" role=\"group\" aria-label=\"レースを選ぶ\"></div><div class=\"toolbar\"><label><input id=\"fpOnlyBuy\" type=\"checkbox\"> 買い候補だけ表示</label><button id=\"fpShowAll\" type=\"button\" aria-pressed=\"false\">この会場の全Rを一覧表示</button></div><p class=\"hint\" id=\"fpSummary\" role=\"status\">保存された予想ファイルを確認しています。</p><div id=\"fpRaces\"></div></section><details class=\"manual\"><summary>ファイルから手動で取り込む（通常は不要）</summary><section><h2>① 予想ファイルを読み込む</h2><p class=\"hint\">ChatGPTで作成した「keiba_nine_...private.json」をiPhoneの「ファイル」に保存し、下から選択。予想ファイル以外は拒否します。</p><label for=\"fpFile\">本人用の前日予想JSON</label><input id=\"fpFile\" type=\"file\" accept=\".json,application/json\"><button id=\"fpImport\" type=\"button\">内容を検査して本人端末に保存</button><p id=\"fpStatus\" role=\"status\">未選択。既存の5項目評価・買い目・購入記録は変更しません。</p></section></details><section><h2>データ管理</h2><p class=\"hint\">削除するのは、端末に手動取り込みした予想ファイルだけ。サーバー上の本人用前日予想は消えません。JRDB前日情報・手動5項目・馬券下書き・実購入記録は触りません。</p><button id=\"fpDelete\" type=\"button\">このページの予想だけ削除（確認あり）</button></section></main><script src=\"/owner-preday-forecast.js\" defer></script></body></html>"
CSS="*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#f0f5ff;font:15px/1.65 system-ui,sans-serif}main{max-width:740px;padding:18px 13px 48px;margin:auto}a{color:#f1cf79}h1{font-size:25px;color:#edc56c}h2{font-size:19px;margin:0 0 12px}section{background:#142d48;border:1px solid #547493;border-radius:15px;padding:14px;margin:16px 0}.warning{background:#322a22;color:#ffe4ad;border:1px solid #927844;border-radius:12px;padding:14px;font-size:14px}.hint{color:#c1d0e3;font-size:13px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center}input[type=file],select{max-width:100%;font-size:16px;background:#0c2136;color:white;border:1px solid #839bb7;border-radius:10px;padding:10px;margin:8px 0}button{font-size:15px;color:#11223b;background:#edc56c;border:0;border-radius:11px;padding:10px 14px;font-weight:bold;cursor:pointer;margin:7px 0}button:disabled{opacity:.5}.card{border:1px solid #52728e;border-radius:12px;background:#10243c;margin:12px 0;padding:12px}.heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.heading strong{font-size:17px}.status{color:#f3deb2;font-size:12px}.line{margin:4px 0;font-weight:600}.label{color:#f3cc72;display:inline-block;min-width:2.5em}.rowbuttons{display:flex;flex-wrap:wrap;gap:10px}.rowbuttons a{display:inline-block;border:1px solid #6c89a3;border-radius:10px;padding:8px 12px}.reason{font-size:13px;color:#ccd9e7}details.manual{margin:18px 0}details.manual summary{color:#edc56c;font-weight:bold;padding:11px;border:1px solid #547493;border-radius:10px;cursor:pointer}.race-evidence{border:1px solid #74869a;border-radius:10px;padding:9px 12px;background:#122b46;margin:10px 0}.race-evidence summary{color:#f0cd84;cursor:pointer;font-weight:800;font-size:15px}.race-evidence p{font-size:13px;margin:8px 0;line-height:1.65;overflow-wrap:anywhere}.race-evidence strong{color:#f1d189}.evidence-warn{color:#f5c4a2}.evidence-facts{border-left:2px solid #83b6a5;padding-left:10px}.selective{background:#152c44;border:1px solid #547493;border-radius:11px;margin:10px 0;padding:8px 10px}.selective summary{cursor:pointer;color:#f2d181;font-weight:750}.selective p{margin:6px 0}.selective ol{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 18px;padding-left:28px;font-variant-numeric:tabular-nums}.selective li{padding:3px 0;font-size:14px}.selective button{font-size:13px;background:#263e5c;color:#f8dd9f;border:1px solid #7994ad}.betting-type{color:#f7d38c;font-weight:750;font-size:13px}.live-brief{border:1px solid #b48a4e;background:#2c2b2b;border-radius:10px;padding:10px 12px;margin:10px 0}.live-brief strong{color:#f3d082}.live-brief p{margin:4px 0;font-size:13px;line-height:1.6}.race-ended{color:#ffc4a6;font-weight:700;font-size:13px;line-height:1.5}.venue-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;position:sticky;top:0;z-index:10;background:#142d48;padding:8px 0}.venue-tabs button{margin:0;min-height:52px;padding:9px 4px;background:#203b55;border:1px solid #66849e;color:#eff6ff;font-size:18px}.venue-tabs button.active{background:#edc56c;border-color:#edc56c;color:#12243a}.race-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:12px 0}.race-tabs button{margin:0;min-height:54px;padding:6px 3px;font-size:14px;background:#213b58;color:#f0f5ff;border:1px solid #53728f;line-height:1.3}.race-tabs button.active{background:#edc56c;color:#12243a;border:1px solid #edc56c}.race-tabs button .race-time{display:block;font-size:11px;font-weight:500;opacity:.82}.toolbar{justify-content:space-between;margin:9px 0}.toolbar label{font-size:13px}.toolbar button{background:#243f59;color:#f0d48f;border:1px solid #718faa;font-size:13px;padding:10px}.card .heading{flex-wrap:wrap;align-items:flex-start}.card .heading strong{font-size:18px;color:#fff}.card .heading span{font-size:13px;color:#f3deb2}.card .bet{padding:8px 10px;border-radius:10px;background:#162f49;margin:8px 0}.card .line{display:flex;gap:12px;align-items:baseline;margin:3px 0;font-size:17px;overflow-wrap:anywhere}.card .label{min-width:2.5em;flex-shrink:0;font-weight:800}.card .reason{overflow-wrap:anywhere}.race-empty{padding:16px 4px;color:#e0cc9e;font-size:14px}@media(max-width:370px){.venue-tabs button{font-size:16px}.race-tabs{gap:5px}.race-tabs button{font-size:13px}.card .line{font-size:15px}}"
JS="(()=>{'use strict';\nconst STORAGE='keiba-nine-owner-preday-analysis-v1';\nconst TRACKS=['東京','京都','福島','札幌','函館','新潟','中山','中京','阪神','小倉'];\nconst $=id=>document.getElementById(id);\nconst MARKER='keiba-nine-private-preday-review-v1';\nlet current=null,serverForecast=null,liveNotes=null,raceEvidence=null,selectedTrack='',selectedRace=1,showAll=false;\nfunction todayJst(){\n const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());\n const fields=Object.fromEntries(parts.map(part=>[part.type,part.value]));\n return fields.year+'-'+fields.month+'-'+fields.day;\n}\nfunction currentJstTime(){\n return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());\n}\nfunction validDate(date){\n if(typeof date!=='string'||!/^20\\d{2}-\\d{2}-\\d{2}$/.test(date))return false;\n const d=new Date(date+'T12:00:00Z');\n return Number.isFinite(d.valueOf())&&d.toISOString().slice(0,10)===date;\n}\nfunction picks(data){\n if(!data||data.schema!==MARKER||!validDate(data.date)||\n   !Array.isArray(data.races)||data.races.length<1||data.races.length>36)\n  throw Error('競馬ナイン本人用の予想ファイルではありません。');\n const seen=new Set(),result=[];\n for(const r of data.races){\n  if(!r||!TRACKS.includes(r.track)||!Number.isInteger(r.race)||\n    r.race<1||r.race>12||typeof r.time!=='string'||\n    !/^([01]\\d|2[0-3]):[0-5]\\d$/.test(r.time)||\n    typeof r.course!=='string'||r.course.length<2||r.course.length>12||\n    !Number.isInteger(r.field)||r.field<3||r.field>18||\n    !Array.isArray(r.rank)||r.rank.length<3||r.rank.length>Math.min(7,r.field)||\n    !['買い候補','見送り'].includes(r.status)||\n    !Number.isInteger(r.confidence)||r.confidence<1||r.confidence>5||\n    r.provisional!==true||r.jraOfficialConfirmed!==false||\n    r.fullFactorVerified!==false||typeof r.note!=='string'||r.note.length>240||\n    !Array.isArray(r.headNames)||r.headNames.length!==r.first.length||\n    r.headNames.some(x=>x!==null&&(typeof x!=='string'||x.length>35)))\n   throw Error('予想の日付・頭数・安全状態・レース欄が不正です。');\n  const key=r.track+'|'+r.race;\n  if(seen.has(key))throw Error('同じ競馬場・同じRが重複しています。');\n  seen.add(key);\n  const known=new Set();\n  if(r.rank.some(x=>!Number.isInteger(x)||x<1||x>r.field||known.has(x)||\n     (known.add(x),false)))throw Error('馬番または評価順が不正です。');\n  if(![r.first,r.second,r.third].every(x=>Array.isArray(x)))throw Error('3連単欄が不正です。');\n  const f=r.first.length,s=r.second.length,t=r.third.length;\n  if(f<1||f>3||s<f||t<s||t>r.rank.length||\n      ![r.first,r.second,r.third].every(a=>a.every((num,i)=>num===r.rank[i])))\n   throw Error('3連単フォーメーションが評価順と一致しません。');\n  const ticket=new Set();\n  for(const a of r.first)for(const b of r.second)for(const c of r.third){\n   if(a!==b&&a!==c&&b!==c)ticket.add([a,b,c].join('-'));\n  }\n  if(!Number.isInteger(r.points)||r.points!==ticket.size||\n     r.points<1||r.points>48)\n   throw Error('3連単の点数が一致しません。');\n  // Store only known presentation data; never persist metadata, source text,\n  // provider metrics, API keys, paid fields or actual purchase information.\n  result.push({track:r.track,race:r.race,time:r.time,course:r.course,\n    rank:[...r.rank],first:[...r.first],second:[...r.second],third:[...r.third],\n    points:r.points,status:r.status,confidence:r.confidence,\n    headNames:[...r.headNames],note:r.note});\n }\n result.sort((a,b)=>TRACKS.indexOf(a.track)-TRACKS.indexOf(b.track)||a.race-b.race);\n return {schema:MARKER,date:data.date,races:result};\n}\nfunction element(tag,text){\n const el=document.createElement(tag);\n if(text!==undefined)el.textContent=String(text);\n return el;\n}\nfunction textLine(parent,title,value){\n const p=element('p');p.className='line';\n const span=element('span',title);span.className='label';\n p.append(span,element('span',value));parent.append(p);\n}\nfunction navButton(title,selected,click,cssClass){\n const b=element('button',title);\n b.type='button';b.className=cssClass+(selected?' active':'');\n b.onclick=click;\n return b;\n}\nfunction bettingStyle(points){\n if(points<=15)return '堅実型';\n if(points<=35)return '標準型';\n return '高配当型';\n}\nfunction selectiveTickets(r){\n // Only selects a distinct subset of the *existing* provisional formation.\n // This is a budget comparison, not an additional bet, paid-data model or odds estimate.\n const order=new Map(r.rank.map((number,index)=>[number,index]));\n const entries=[];\n for(const a of r.first)for(const b of r.second)for(const c of r.third){\n  if(a===b||a===c||b===c)continue;\n  const i=order.get(a),j=order.get(b),k=order.get(c);\n  const score=100-12*i-5*j-1.5*k+(k>=4?4:0)+(r.points>35&&i>=1?6:0);\n  entries.push({a,b,c,score});\n }\n entries.sort((x,y)=>y.score-x.score||x.a-y.a||x.b-y.b||x.c-y.c);\n const max=Math.min(r.points,r.points<=15?6:r.points<=35?10:12);\n const chosen=[],used=new Set();\n function add(t){\n  if(!t||chosen.length>=max)return;\n  const key=t.a+'-'+t.b+'-'+t.c;\n  if(used.has(key))return;\n  chosen.push([t.a,t.b,t.c]);used.add(key);\n }\n // Represent every predicted winner, and keep some outside third candidates.\n for(const a of r.first)add(entries.find(x=>x.a===a));\n for(const a of r.first)add(entries.find(x=>x.a===a&&order.get(x.c)>=4));\n for(const ticket of entries)add(ticket);\n return chosen;\n}\nfunction render(){\n const host=$('fpRaces'),venues=$('fpVenueTabs'),raceTabs=$('fpRaceTabs');\n host.replaceChildren();venues.replaceChildren();raceTabs.replaceChildren();\n if(!current){\n  $('fpSummary').textContent='まだ本人用の予想が届いていません。配信状況を確認してな。';\n  return;\n }\n if(current.date<todayJst()){\n  $('fpSummary').textContent=current.date+'の古い暫定予想は非表示です。新しい開催日の予想が届くと自動で切り替わります。';\n  return;\n }\n const available=TRACKS.filter(t=>current.races.some(r=>r.track===t));\n if(!available.includes(selectedTrack)){\n  selectedTrack=available[0]||'';selectedRace=1;showAll=false;\n }\n const entries=current.races.filter(r=>r.track===selectedTrack);\n if(!entries.some(r=>r.race===selectedRace))selectedRace=entries[0]?.race||1;\n for(const t of available){\n  const count=current.races.filter(r=>r.track===t).length;\n  const b=navButton(t+' '+count+'R',t===selectedTrack,()=>{\n   selectedTrack=t;selectedRace=1;showAll=false;render();\n  },'venue-button');\n  b.setAttribute('aria-pressed',String(t===selectedTrack));\n  venues.append(b);\n }\n for(const r of entries){\n  const b=navButton(r.race+'R '+r.time,selectedRace===r.race&&!showAll,()=>{\n   selectedRace=r.race;showAll=false;render();\n  },'race-button');\n  b.setAttribute('aria-pressed',String(selectedRace===r.race&&!showAll));\n  raceTabs.append(b);\n }\n const toggle=$('fpShowAll');\n toggle.textContent=showAll?'1Rずつ見る':'この会場の全Rを一覧表示';\n toggle.setAttribute('aria-pressed',String(showAll));\n const buy=$('fpOnlyBuy').checked;\n const rows=entries.filter(r=>(showAll||r.race===selectedRace)&&(!buy||r.status==='買い候補'));\n $('fpSummary').textContent=current.date+'｜'+selectedTrack+' '+entries.length+'R中'+(showAll?'全R':selectedRace+'R')+\n  '（表示'+rows.length+'R）。前日暫定・当日JRA未照合。';\n if(!rows.length){\n  const p=element('p','該当するレースがありません。「買い候補だけ表示」を解除するか、別のRを選んでな。');\n  p.className='race-empty';host.append(p);return;\n }\n for(const r of rows){\n  const card=element('article');card.className='card';\n  const head=element('div');head.className='heading';\n  head.append(element('strong',r.track+r.race+'R '+r.time+' '+r.course),\n    element('span',r.status+'／勝負度'+r.confidence+'/5'));\n  head.append(element('span','3連単 '+bettingStyle(r.points)+'｜'+r.points+'点'));\n  card.append(head);\n  if(r.points>35){\n   const tip=element('p','高配当型：10万〜30万円級も視野に入れる構成。ただし想定配当を確認したものではなく、高額的中を保証しません。');\n   tip.className='reason';card.append(tip);\n  }\n  const alreadyStarted=current.date===todayJst()&&currentJstTime()>=r.time;\n  if(alreadyStarted){\n   const warning=element('p','発走予定時刻を経過。後から予想を変更しません。購入対象外です。');\n   warning.className='race-ended';card.append(warning);\n  }\n  const live=liveNotes&&liveNotes.date===current.date&&liveNotes.races.find(\n   x=>x.track===r.track&&x.race===r.race&&x.time===r.time);\n  if(live){\n   const box=element('section');box.className='live-brief';\n   box.append(element('strong','JRDB当日直前情報（'+live.observedAt+'受信分）'));\n   box.append(element('p','報告馬場：'+live.ground+'／パドック注目馬番：'+live.paddock.join('・')));\n   box.append(element('p',live.note));\n   box.append(element('p','既存の3連単は前日暫定のまま。JRA公式の取消・馬場確認は別途必要。'));\n   card.append(box);\n  }\n  const winner=r.first.map((n,i)=>n+' '+(r.headNames[i]||'')).join('・');\n  const p=element('p','1着候補：'+winner);card.append(p);\n  const order=element('p','良い馬順（暫定）：'+r.rank.join(' > '));order.className='reason';card.append(order);\n  const group=element('div');group.className='bet';\n  textLine(group,'1着',r.first.join(' '));\n  textLine(group,'2着',r.second.join(' '));\n  textLine(group,'3着',r.third.join(' '));\n  group.append(element('p','3連単 '+r.points+'点／各100円なら'+(r.points*100).toLocaleString('ja-JP')+'円'));\n  card.append(group);\n  const basis=raceEvidence&&raceEvidence.date===current.date&&raceEvidence.races.find(\n   item=>item.track===r.track&&item.race===r.race);\n  if(basis){\n   const details=element('details');details.className='race-evidence';\n   details.append(element('summary','買い目の根拠・未確認項目を開く'));\n   for(const h of basis.lead){\n    const reason=element('p');reason.append(element('strong','1着候補 '+h.number+' '+h.name+'：'));\n    reason.append(element('span',h.reason));details.append(reason);\n   }\n   for(const [title,value] of [['展開の仮説',basis.pace],['2・3着を選ぶ理由',basis.secondThird],\n     ['バラ買いの考え方',basis.singles]]){\n    const item=element('p');\n    item.append(element('strong',title+'：'),element('span',value));\n    details.append(item);\n   }\n   for(const fact of basis.verifiedFacts){\n    const p=element('p',fact);p.className='evidence-facts';details.append(p);\n   }\n   const sources=element('p','資料の確認状況：前日情報あり／JRA近走'+\n    (basis.coverage.officialPastRuns?'確認済（対象R）':'未照合')+'／調教'+\n    (basis.coverage.publicTrainingChecked?'一部公開情報を確認':'未照合')+'／血統'+\n    (basis.coverage.officialPedigreeChecked?'一部確認':'未照合'));\n   sources.className='reason';details.append(sources);\n   const risk=element('p','最終確認が必要：'+basis.risk);\n   risk.className='evidence-warn';details.append(risk);\n   card.append(details);\n  }\n  const singles=selectiveTickets(r);\n  if(singles.length){\n   const details=element('details');details.className='selective';\n   details.append(element('summary','バラ買い比較案 '+singles.length+'点／'+\n     (singles.length*100).toLocaleString('ja-JP')+'円（開く）'));\n   const hint=element('p','上のフォーメーションから順序を絞った個別3連単。追加購入ではなく別案です。人気・オッズ・実払戻を検証した選定ではありません。');\n   hint.className='reason';details.append(hint);\n   const list=element('ol');\n   for(const ticket of singles)list.append(element('li',ticket.join(' → ')));\n   details.append(list);\n   const copySingles=element('button','バラ買い案をコピー');\n   copySingles.onclick=()=>{\n    const text=r.track+r.race+'R 個別3連単（前日暫定・フォーメーションの代替案）\\n'+\n     singles.map(t=>t.join('→')).join('\\n')+'\\n'+singles.length+'点×100円';\n    if(navigator?.clipboard?.writeText)\n     navigator.clipboard.writeText(text).then(()=>copySingles.textContent='コピー済み')\n      .catch(()=>copySingles.textContent='買い目を長押しコピーしてな。');\n    else copySingles.textContent='買い目を長押しコピーしてな。';\n   };\n   details.append(copySingles);card.append(details);\n  }\n  const note=element('p',r.note);note.className='reason';card.append(note);\n  const nav=element('div');nav.className='rowbuttons';\n  const link=element('a','同じRの評価画面へ');\n  link.href='/my-scorecard#'+new URLSearchParams({\n    select:'v1',date:current.date,track:r.track,race:String(r.race)\n  }).toString();\n  nav.append(link);\n  const copy=element('button','フォーメーションをコピー');\n  const msg=r.track+r.race+'R 1着 '+r.first.join(',')+\n    ' / 2着 '+r.second.join(',')+' / 3着 '+r.third.join(',')+' = '+r.points+'点（前日暫定）';\n  copy.onclick=()=>{if(navigator?.clipboard?.writeText)\n    navigator.clipboard.writeText(msg).then(()=>copy.textContent='コピー済み')\n      .catch(()=>copy.textContent='画面の買い目を長押しコピーしてな。');\n    else copy.textContent='画面の買い目を長押しコピーしてな。';\n  };\n  nav.append(copy);card.append(nav);host.append(card);\n }\n}\n$('fpFile').onchange=()=>{$('fpStatus').textContent=\n $('fpFile').files?.[0]?'選択済み。検査ボタンで読み込めます。':'ファイル未選択。';};\n$('fpOnlyBuy').onchange=render;$('fpShowAll').onclick=()=>{showAll=!showAll;render();};\n$('fpImport').onclick=async()=>{\n try{\n  const file=$('fpFile').files?.[0];\n  if(!file||file.size<=0||file.size>200000)throw Error('200KB以内のJSONファイルを選んでな。');\n  const content=await file.text();\n  if(content.length>200000)throw Error('予想ファイルが大きすぎます。');\n  const result=picks(JSON.parse(content));\n  if(!confirm(result.date+'・'+result.races.length+'Rの前日暫定予想をこのiPhoneに保存しますか？\\n実購入・5項目評価・馬券下書きは変更しません。'))return;\n  localStorage.setItem(STORAGE,JSON.stringify(result));\n  current=result;render();\n  $('fpStatus').textContent=result.date+'の'+result.races.length+\n    'Rを保存しました。JRA当日確認・AI評価は未完了です。';\n }catch(e){$('fpStatus').textContent='取り込めません：'+\n   (e instanceof Error?e.message:'内容を確認してな。');}\n};\n$('fpRefresh').onclick=()=>{loadOwnerForecast();loadOwnerLiveNotes();loadRaceEvidence();};\nasync function loadRaceEvidence(){\n try{\n  const response=await fetch('/api/owner-race-evidence',{\n   cache:'no-store',credentials:'same-origin',\n   headers:{'X-Keiba-Request':'private','Accept':'application/json'}\n  });\n  if(!response.ok)throw Error('Unavailable');\n  const data=await response.json();\n  if(data?.available!==true){\n   raceEvidence=null;\n   $('fpEvidenceStatus').textContent='この開催日の根拠メモは未登録です。';\n   render();return;\n  }\n  const v=data.evidence;\n  if(!v||v.sourceKind!=='owner-editorial-limited-evidence'||\n    v.finalVerified!==false||v.predictionRevised!==false||\n    !validDate(v.date)||!Array.isArray(v.races)||v.races.length!==36)\n   throw Error('Invalid');\n  const seen=new Set();\n  for(const r of v.races){\n   if(!r||!TRACKS.includes(r.track)||!Number.isInteger(r.race)||\n      typeof r.risk!=='string'||typeof r.pace!=='string'||\n      typeof r.secondThird!=='string'||typeof r.singles!=='string'||\n      !Array.isArray(r.verifiedFacts)||!Array.isArray(r.lead)||\n      !r.lead.every(h=>Number.isInteger(h.number)&&typeof h.name==='string'&&\n         typeof h.reason==='string')||\n      !r.coverage||r.coverage.dayOfScratchesAndTrackChecked!==false||\n      r.coverage.allHorseTrainingChecked!==false)\n     throw Error('Invalid');\n   const key=r.track+'|'+r.race;\n   if(seen.has(key))throw Error('Duplicate');\n   seen.add(key);\n  }\n  raceEvidence=v;\n  $('fpEvidenceStatus').textContent=v.date+'｜36Rの根拠メモを表示。前日資料からの仮説と確認済みの事実を区別しています。';\n  render();\n }catch(_){\n  $('fpEvidenceStatus').textContent='根拠メモの表示を確認できません。買い目は元の暫定案のままです。';\n }\n}\nfunction showMailBridgeStatus(data){\n const sync=data&&data.sync;\n const label=sync&&sync.configured===true\n  ?(sync.status==='接続済み'\n    ?'Gmail自動連携：接続済み。直前メールの受信分を反映（買い目は自動変更しません）。'\n    :'Gmail自動連携：接続設定あり・通信要確認。直前メモの手動分を優先。')\n  :'Gmail自動連携：初回設定がまだです。前日予想は表示できます。';\n $('fpMailBridgeStatus').textContent=label;\n}\nasync function loadOwnerLiveNotes(){\n try{\n  const response=await fetch('/api/owner-live-notes',{\n   credentials:'same-origin',cache:'no-store',\n   headers:{'X-Keiba-Request':'private','Accept':'application/json'}\n  });\n  if(!response.ok)throw Error('Unavailable');\n  const data=await response.json();\n  showMailBridgeStatus(data);\n  if(!data||data.available!==true){\n   liveNotes=null;\n   $('fpLiveStatus').textContent='当日の直前メモは未登録。前日参考予想を表示します。';\n   render();return;\n  }\n  const notes=data.notes;\n  if(!notes||!validDate(notes.date)||notes.sourceKind!=='owner-edited-live-brief'||\n      notes.officialJraVerified!==false||notes.predictionReady!==false||\n      !Array.isArray(notes.races)||notes.races.length>36)throw Error('Invalid');\n  for(const r of notes.races){\n   if(!r||!TRACKS.includes(r.track)||!Number.isInteger(r.race)||\n       !Array.isArray(r.paddock)||!r.paddock.every(Number.isInteger)||\n       typeof r.observedAt!=='string'||typeof r.time!=='string'||\n       typeof r.ground!=='string'||typeof r.note!=='string')throw Error('Invalid');\n  }\n  liveNotes=notes;\n  $('fpLiveStatus').textContent=notes.date+'・'+notes.races.length+\n   'R分の直前情報を追加表示。これは前日買い目の上書き・最終確定ではありません。';\n  render();\n }catch(_){\n  $('fpLiveStatus').textContent='直前情報は未確認。前日暫定予想を維持しています。';\n  $('fpMailBridgeStatus').textContent='Gmail自動連携：現在の接続状態を確認できません。';\n }\n}\nasync function loadOwnerForecast(){\n $('fpCloudStatus').textContent='非公開の本人用予想を確認しています。';\n try{\n  const response=await fetch('/api/owner-preday-forecast',{\n   credentials:'same-origin',cache:'no-store',\n   headers:{'X-Keiba-Request':'private','Accept':'application/json'}\n  });\n  if(!response.ok)throw Error('非公開予想を取得できません。');\n  const result=await response.json();\n  if(!result||typeof result!=='object'||result.available!==true){\n   $('fpCloudStatus').textContent='サーバー上の前日予想はまだ未設定。手動取込データがあれば表示します。';\n   return;\n  }\n  const safe=picks(result.forecast);\n  if(!result.forecast||result.forecast.sourceKind!=='owner-private-authored-preday'||\n     result.forecast.predictionReady!==false||result.forecast.officialJraVerified!==false||\n     result.forecast.purchased!==false||result.forecast.raceCount!==safe.races.length)\n   throw Error('非公開予想の安全表示情報が一致しません。');\n  serverForecast=safe;\n  if(current&&current.date>safe.date){\n   $('fpCloudStatus').textContent='サーバーの'+safe.date+'の予想より、端末内の'+current.date+'の暫定予想が新しいため、端末の内容を維持しています。';\n   render();return;\n  }\n  current=safe;\n  $('fpCloudStatus').textContent=safe.date+'｜'+safe.races.length+\n   'Rを本人用サーバーから自動表示。ファイルの選択・保存は不要。前日暫定／当日JRA未照合。';\n  render();\n }catch(_){\n  $('fpCloudStatus').textContent='サーバーの予想表示を確認できません。既存の端末内予想があれば閲覧できます。';\n }\n}\n$('fpDelete').onclick=()=>{\n if(!current)return;\n if(!confirm('本人用の取り込み済み前日予想だけを削除しますか？\\n既存の馬券・採点・JRDB前日情報は残ります。'))return;\n try{localStorage.removeItem(STORAGE);current=serverForecast;render();\n  $('fpStatus').textContent='端末の手動取込データだけ削除。サーバーの予想は維持されます。';\n }catch(e){$('fpStatus').textContent='削除できません。端末の保存設定を確認してな。';}\n};\ntry{\n const raw=localStorage.getItem(STORAGE);\n if(raw){current=picks(JSON.parse(raw));\n   $('fpStatus').textContent='端末に保存済みの前日暫定予想を表示しています。';}\n render();\n}catch(_){current=null;$('fpSummary').textContent='端末の保存資料を読み込めません。サーバーを確認します。';}\nlet nextAutoCheck=0;\nfunction refreshOnReturn(){\n if(document.visibilityState==='hidden'||Date.now()<nextAutoCheck)return;\n nextAutoCheck=Date.now()+60000;\n loadOwnerForecast();\n loadOwnerLiveNotes();\n loadRaceEvidence();\n}\nif(typeof window!=='undefined'&&typeof window.addEventListener==='function')\n window.addEventListener('pageshow',e=>{if(e.persisted)refreshOnReturn();});\nif(typeof document.addEventListener==='function')\n document.addEventListener('visibilitychange',refreshOnReturn);\nrefreshOnReturn();\n// While this screen is open, refresh only the read-only prestart digest.\n// No browser background polling, forecast overwrite or purchase storage writes.\nif(typeof setInterval==='function')setInterval(()=>{\n if(document.visibilityState!=='hidden')loadOwnerLiveNotes();\n},60000);\n})();"
